const msg = $('Telegram Trigger').first().json.message;
const caption = msg.caption || '';
const g = $input.first().json;
let text = '';
if (g.content && g.content.parts) text = g.content.parts.map(function (p) { return p.text || ''; }).join('');
else if (typeof g.text === 'string') text = g.text;
else if (typeof g.output === 'string') text = g.output;
else text = JSON.stringify(g);

let p = {};
let parseError = null;
try {
  const s = text.indexOf('{');
  const e = text.lastIndexOf('}');
  p = JSON.parse(text.slice(s, e + 1));
} catch (err) {
  parseError = err.message;
}

const str = function (v) { return (typeof v === 'string' && v.trim() && v.trim().toLowerCase() !== 'null') ? v.trim() : null; };
const list = function (v) { return Array.isArray(v) ? v.map(function (x) { return String(x).trim(); }).filter(Boolean) : []; };
const num = function (v) {
  if (v === null || v === undefined || v === '') return null;
  const n = parseFloat(String(v).replace(/[^0-9.]/g, ''));
  return isNaN(n) ? null : n;
};

// Anti-hallucination guard: seller details must literally appear in the caption.
const tokens = new Set(caption.toLowerCase().split(/[^a-z0-9]+/).filter(Boolean));
const inCaption = function (v) {
  return String(v).toLowerCase().split(/[^a-z0-9]+/).filter(Boolean).every(function (t) { return tokens.has(t); });
};
const capNums = (caption.replace(/,/g, '').match(/[0-9]+([.][0-9]+)?/g) || []).map(parseFloat);

let price = num(p.price);
if (price === null) {
  const pm = caption.replace(/,/g, '').match(/(?:price|rs[.]?|pkr|usd|[$])[ ]*[:=-]?[ ]*([0-9]+(?:[.][0-9]+)?)/i) || caption.replace(/,/g, '').match(/([0-9]+(?:[.][0-9]+)?)[ ]*(?:pkr|rs|usd|[$])/i);
  if (pm) price = parseFloat(pm[1]);
}
if (price !== null && capNums.indexOf(price) === -1) price = null;
let inventory = num(p.inventory);
if (inventory !== null) {
  inventory = Math.round(inventory);
  if (capNums.indexOf(inventory) === -1) inventory = null;
}
let sku = str(p.sku);
if (sku && !inCaption(sku)) sku = null;
const uniq = function (a) { return a.filter(function (v, i) { return a.indexOf(v) === i; }); };
const sizes = uniq(list(p.sizes).filter(inCaption));
const colors = uniq(list(p.colors).filter(inCaption));

const title = str(p.title);
const missing = [];
if (parseError || !title) missing.push('AI analysis failed (' + (parseError || 'no title') + ')');
if (price === null) missing.push('price');

const notProvided = [];
if (!sizes.length) notProvided.push('sizes');
if (!colors.length) notProvided.push('colors');
if (!sku) notProvided.push('SKU');
if (inventory === null) notProvided.push('inventory');

const options = [];
if (sizes.length) options.push({ name: 'Size', values: sizes });
if (colors.length) options.push({ name: 'Color', values: colors });
let combos = [[]];
options.forEach(function (o) {
  const next = [];
  combos.forEach(function (c) { o.values.forEach(function (v) { next.push(c.concat([{ optionName: o.name, name: v }])); }); });
  combos = next;
});
if (!options.length) {
  options.push({ name: 'Title', values: ['Default Title'] });
  combos = [[{ optionName: 'Title', name: 'Default Title' }]];
}
const variants = combos.map(function (c) {
  const v = { optionValues: c, price: String(price === null ? 0 : price.toFixed(2)) };
  if (sku) {
    v.sku = combos.length > 1 ? sku + '-' + c.map(function (x) { return x.name.toUpperCase().replace(/[^A-Z0-9]/g, ''); }).join('-') : sku;
  }
  return v;
});

const status = $('Settings').first().json.publish_automatically === true ? 'ACTIVE' : 'DRAFT';
const bin = $('Telegram Trigger').first().binary;
const bd = bin && bin.data ? bin.data : {};
const mime = bd.mimeType || 'image/jpeg';
const ext = bd.fileExtension || 'jpg';

const stageBody = {
  query: 'mutation stagedUploadsCreate($input: [StagedUploadInput!]!) { stagedUploadsCreate(input: $input) { stagedTargets { url resourceUrl parameters { name value } } userErrors { field message } } }',
  variables: { input: [{ resource: 'IMAGE', filename: 'product-' + msg.message_id + '.' + ext, mimeType: mime, httpMethod: 'POST' }] },
};

return [{
  json: {
    ready: missing.length === 0,
    missing: missing,
    notProvided: notProvided.join(', '),
    chatId: msg.chat.id,
    status: status,
    product: {
      title: title,
      descriptionHtml: str(p.descriptionHtml) || '',
      tags: list(p.tags),
      productType: str(p.productType) || '',
      seoTitle: str(p.seoTitle) || title,
      seoDescription: str(p.seoDescription) || '',
    },
    options: options,
    variants: variants,
    inventory: inventory,
    stageBody: stageBody,
  },
}];

const res = $input.first().json;
const t = res.data && res.data.stagedUploadsCreate && res.data.stagedUploadsCreate.stagedTargets && res.data.stagedUploadsCreate.stagedTargets[0];
if (!t) throw new Error('Shopify staged upload failed: ' + JSON.stringify(res.errors || res.data || res));
const params = {};
t.parameters.forEach(function (p) { params[p.name] = p.value; });
const bin = $('Telegram Trigger').first().binary;
if (!bin || !bin.data) throw new Error('The Telegram image was not downloaded (no binary data on the trigger item).');
return [{ json: { uploadUrl: t.url, resourceUrl: t.resourceUrl, params: params }, binary: { data: bin.data } }];

const d = $('Parse AI result').first().json;
const up = $('Build upload form').first().json;
const loc = $input.first().json;
const nodes = loc && loc.data && loc.data.locations && loc.data.locations.nodes;
const locationId = nodes && nodes[0] ? nodes[0].id : null;

const variants = d.variants.map(function (v) {
  const out = { optionValues: v.optionValues, price: v.price };
  if (v.sku) out.sku = v.sku;
  if (d.inventory !== null && locationId) {
    out.inventoryItem = { tracked: true };
    out.inventoryQuantities = [{ locationId: locationId, name: 'available', quantity: d.inventory }];
  }
  return out;
});

const input = {
  title: d.product.title,
  descriptionHtml: d.product.descriptionHtml,
  productType: d.product.productType,
  tags: d.product.tags,
  status: d.status,
  seo: { title: d.product.seoTitle, description: d.product.seoDescription },
  productOptions: d.options.map(function (o) { return { name: o.name, values: o.values.map(function (n) { return { name: n }; }) }; }),
  variants: variants,
  files: [{ originalSource: up.resourceUrl, contentType: 'IMAGE', alt: d.product.title }],
};

return [{ json: { body: {
  query: 'mutation productSet($input: ProductSetInput!) { productSet(input: $input, synchronous: true) { product { id handle status onlineStoreUrl } userErrors { field message code } } }',
  variables: { input: input },
}, inventorySkipped: d.inventory !== null && !locationId } }];

const res = $input.first().json;
const pubs = (res && res.data && res.data.publications && res.data.publications.nodes) || [];
const op = pubs.find(function (p) { return /online store/i.test(p.name || ''); });
const prod = $('Create Shopify product').first().json.data.productSet.product;
return [{ json: { channelFound: !!op, body: {
  query: 'mutation publishablePublish($id: ID!, $input: [PublicationInput!]!) { publishablePublish(id: $id, input: $input) { userErrors { field message } } }',
  variables: { id: prod.id, input: op ? [{ publicationId: op.id }] : [] },
} } }];

